        rng.shuffle(order)

        chosen_routes: set[int] = set()
        freed = 0
        for idx in order:
            chosen_routes.add(idx)
            freed += len(routes[idx])
            if freed >= target:
                break

        chosen_customers = {c for idx in chosen_routes for c in routes[idx]}

